import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Orchestrator Meeting 2020-10-05","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2020-10-05","date":"2020-10-05T00:00:00.000Z","updated":"2020-10-07T00:00:00.000Z","tags":["Ceph","Orchestrator","Rook","Kubernetes","Storage Management"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-10-05.md","filePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-10-05.md","lastUpdated":1780460162000}'),i={name:"posts/2020/Ceph_Orchestrator_Meeting_2020-10-05.md"};function l(h,a,n,s,d,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-rook-manager-module-的现状和未来" tabindex="-1">会议主题：Rook Manager Module 的现状和未来 <a class="header-anchor" href="#会议主题-rook-manager-module-的现状和未来" aria-label="Permalink to &quot;会议主题：Rook Manager Module 的现状和未来&quot;">​</a></h4><h4 id="参会人员-未明确列出-但提到了patrick、travis、joshua等人。" tabindex="-1">参会人员：未明确列出，但提到了Patrick、Travis、Joshua等人。 <a class="header-anchor" href="#参会人员-未明确列出-但提到了patrick、travis、joshua等人。" aria-label="Permalink to &quot;参会人员：未明确列出，但提到了Patrick、Travis、Joshua等人。&quot;">​</a></h4><h4 id="会议时间-未明确列出-但提到了几天前发送的邮件。" tabindex="-1">会议时间：未明确列出，但提到了几天前发送的邮件。 <a class="header-anchor" href="#会议时间-未明确列出-但提到了几天前发送的邮件。" aria-label="Permalink to &quot;会议时间：未明确列出，但提到了几天前发送的邮件。&quot;">​</a></h4><h4 id="会议地点-未明确列出-通过视频会议进行。" tabindex="-1">会议地点：未明确列出，通过视频会议进行。 <a class="header-anchor" href="#会议地点-未明确列出-通过视频会议进行。" aria-label="Permalink to &quot;会议地点：未明确列出，通过视频会议进行。&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><strong>Rook Manager Module 的现状和需求</strong>：讨论了该模块的维护状态、优先级和是否仍需保留，并确认了Dashboard对该模块的兴趣。</li><li><strong>模块的启用状态和社区反馈</strong>：指出模块未默认启用，社区未注意到或询问原因，并发现了多个bug，但缺乏测试。</li><li><strong>资源和优先级问题</strong>：讨论了资源有限，当前主要优先级是FDM（Federated Deployment Manager），Red Hat和SUSE的资源分配问题。</li><li><strong>功能和测试需求</strong>：需要确定模块的具体使用场景和功能需求，强调测试的重要性，特别是与Rook和Cephadm的集成测试。</li><li><strong>未来方向</strong>：讨论了是否应继续支持模块，以及如何分配资源，提出了可能的解决方案。</li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>需要进一步明确模块的使用场景和功能需求。</li><li>需要加强测试，特别是与Rook和Cephadm的集成测试。</li><li>需要讨论资源分配问题，特别是如何平衡FDM和模块的开发资源。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续讨论模块的未来方向和资源分配。</li><li>加强测试，特别是与Rook和Cephadm的集成测试。</li><li>需要明确Dashboard对模块的需求和使用场景。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论： <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论：&quot;">​</a></h4><ul><li>讨论了SSH和HTTPS在获取主机信息方面的性能和安全性问题。</li><li>认为需要在真实硬件上测试SSH的性能，以决定是否继续使用或切换到HTTPS。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>会议主要讨论了Rook Manager Module的现状、需求、资源分配和未来方向。强调了测试的重要性，并提出了需要进一步明确的使用场景和功能需求。同时，讨论了SSH和HTTPS在获取主机信息方面的性能和安全性问题，并提出了需要在真实硬件上进行进一步测试的建议。</p><p>以上是根据会议内容总结的会议纪要，涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。</p>',16)])])}const _=e(i,[["render",l]]);export{p as __pageData,_ as default};
